T = int(input())
for _ in range(T):
	(N, M, K) = map(int, input().split())
	res = 0
	for j in range(1, M + 1):
		if j <= N and j % 2 == 1:
			res = res ^ K + j + 1
		elif j > N and N % 2 == 1:
			res = res ^ K + j + 1
	for j in range(M + 1, N + M):
		if j > N and (N + M - j) % 2 == 1:
			res = res ^ K + j + 1
		elif j <= N and M % 2 == 1:
			res = res ^ K + j + 1
	print(res)
